mapper.select:
select
    *
from t_camera_preset
where camera_id = #{cameraId}
and preset_type <> 1
 and preset_id <> #{selfPreset, jdbcType=BIGINT}

select count(1)
FROM t_camera_info a, t_camera_preset b
WHERE a.camera_id = b.camera_id
  and b.preset_type = 3
  and a.camera_id = #{cameraId}
  and b.preset_id = #{presetId}

